INSERT INTO repo_sdg_targets (sdg_target_id, target_code, text, status) VALUES ('SDG_TARGET_6_4', '6.4', 'By 2030, substantially increase water-use efficiency across all sectors and ensure sustainable withdrawals and supply of freshwater to address water scarcity and substantially reduce the number of people suffering from water scarcity', 'Active'), ('SDG_TARGET_6_5', '6.5', 'By 2030, implement integrated water resources management at all levels, including through transboundary cooperation as appropriate', 'Active'), ('SDG_TARGET_6_6', '6.6', 'By 2020, protect and restore water-related ecosystems, including mountains, forests, wetlands, rivers, aquifers and lakes', 'Active'), ('SDG_TARGET_6_a', '6.a', 'By 2030, expand international cooperation and capacity-building support to developing countries in water- and sanitation-related activities and programmes, including water harvesting, desalination, water efficiency, wastewater treatment, recycling and reuse technologies', 'Active'), ('SDG_TARGET_6_b', '6.b', 'Support and strengthen the participation of local communities in improving water and sanitation management', 'Active'), ('SDG_TARGET_7_1', '7.1', 'By 2030, ensure universal access to affordable, reliable and modern energy services', 'Active'), ('SDG_TARGET_7_2', '7.2', 'By 2030, increase substantially the share of renewable energy in the global energy mix', 'Active'), ('SDG_TARGET_7_3', '7.3', 'By 2030, double the global rate of improvement in energy efficiency', 'Active'), ('SDG_TARGET_7_a', '7.a', 'By 2030, enhance international cooperation to facilitate access to clean energy research and technology, including renewable energy, energy efficiency and advanced and cleaner fossil-fuel technology, and promote investment in energy infrastructure and clean energy technology', 'Active'), ('SDG_TARGET_7_b', '7.b', 'By 2030, expand infrastructure and upgrade technology for supplying modern and sustainable energy services for all in developing countries, in particular least developed countries, small island developing States and landlocked developing countries, in accordance with their respective programmes of support', 'Active'), ('SDG_TARGET_8_1', '8.1', 'Sustain per capita economic growth in accordance with national circumstances and, in particular, at least 7 per cent gross domestic product growth per annum in the least developed countries', 'Active'), ('SDG_TARGET_8_10', '8.10', 'Strengthen the capacity of domestic financial institutions to encourage and expand access to banking, insurance and financial services for all', 'Active'), ('SDG_TARGET_8_2', '8.2', 'Achieve higher levels of economic productivity through diversification, technological upgrading and innovation, including through a focus on high-value added and labour-intensive sectors', 'Active'), ('SDG_TARGET_8_3', '8.3', 'Promote development-oriented policies that support productive activities, decent job creation, entrepreneurship, creativity and innovation, and encourage the formalization and growth of micro-, small- and medium-sized enterprises, including through access to financial services', 'Active'), ('SDG_TARGET_8_4', '8.4', 'Improve progressively, through 2030, global resource efficiency in consumption and production and endeavour to decouple economic growth from environmental degradation, in accordance with the 10-Year Framework of Programmes on Sustainable Consumption and Production, with developed countries taking the lead', 'Active'), ('SDG_TARGET_8_5', '8.5', 'By 2030, achieve full and productive employment and decent work for all women and men, including for young people and persons with disabilities, and equal pay for work of equal value', 'Active'), ('SDG_TARGET_8_6', '8.6', 'By 2020, substantially reduce the proportion of youth not in employment, education or training', 'Active'), ('SDG_TARGET_8_7', '8.7', 'Take immediate and effective measures to eradicate forced labour, end modern slavery and human trafficking and secure the prohibition and elimination of the worst forms of child labour, including recruitment and use of child soldiers, and by 2025 end child labour in all its forms', 'Active'), ('SDG_TARGET_8_8', '8.8', 'Protect labour rights and promote safe and secure working environments for all workers, including migrant workers, in particular women migrants, and those in precarious employment', 'Active'), ('SDG_TARGET_8_9', '8.9', 'By 2030, devise and implement policies to promote sustainable tourism that creates jobs and promotes local culture and products', 'Active'), ('SDG_TARGET_8_a', '8.a', 'Increase Aid for Trade support for developing countries, in particular least developed countries, including through the Enhanced Integrated Framework for Trade-related Technical Assistance to Least Developed Countries', 'Active'), ('SDG_TARGET_8_b', '8.b', 'By 2020, develop and operationalize a global strategy for youth employment and implement the Global Jobs Pact of the International Labour Organization', 'Active'), ('SDG_TARGET_9_1', '9.1', 'Develop quality, reliable, sustainable and resilient infrastructure, including regional and transborder infrastructure, to support economic development and human well-being, with a focus on affordable and equitable access for all', 'Active'), ('SDG_TARGET_9_2', '9.2', 'Promote inclusive and sustainable industrialization and, by 2030, significantly raise industry’s share of employment and gross domestic product, in line with national circumstances, and double its share in least developed countries', 'Active'), ('SDG_TARGET_9_3', '9.3', 'Increase the access of small-scale industrial and other enterprises, in particular in developing countries, to financial services, including affordable credit, and their integration into value chains and markets', 'Active'), ('SDG_TARGET_9_4', '9.4', 'By 2030, upgrade infrastructure and retrofit industries to make them sustainable, with increased resource-use efficiency and greater adoption of clean and environmentally sound technologies and industrial processes, with all countries taking action in accordance with their respective capabilities', 'Active'), ('SDG_TARGET_9_5', '9.5', 'Enhance scientific research, upgrade the technological capabilities of industrial sectors in all countries, in particular developing countries, including, by 2030, encouraging innovation and substantially increasing the number of research and development workers per 1 million people and public and private research and development spending', 'Active'), ('SDG_TARGET_9_a', '9.a', 'Facilitate sustainable and resilient infrastructure development in developing countries through enhanced financial, technological and technical support to African countries, least developed countries, landlocked developing countries and small island developing States', 'Active'), ('SDG_TARGET_9_b', '9.b', 'Support domestic technology development, research and innovation in developing countries, including by ensuring a conducive policy environment for, inter alia, industrial diversification and value addition to commodities', 'Active'), ('SDG_TARGET_9_c', '9.c', 'Significantly increase access to information and communications technology and strive to provide universal and affordable access to the Internet in least developed countries by 2020', 'Active'), ('SDG_TARGET_10_1', '10.1', 'By 2030, progressively achieve and sustain income growth of the bottom 40 per cent of the population at a rate higher than the national average', 'Active'), ('SDG_TARGET_10_2', '10.2', 'By 2030, empower and promote the social, economic and political inclusion of all, irrespective of age, sex, disability, race, ethnicity, origin, religion or economic or other status', 'Active'), ('SDG_TARGET_10_3', '10.3', 'Ensure equal opportunity and reduce inequalities of outcome, including by eliminating discriminatory laws, policies and practices and promoting appropriate legislation, policies and action in this regard', 'Active'), ('SDG_TARGET_10_4', '10.4', 'Adopt policies, especially fiscal, wage and social protection policies, and progressively achieve greater equality', 'Active'), ('SDG_TARGET_10_5', '10.5', 'Improve the regulation and monitoring of global financial markets and institutions and strengthen the implementation of such regulations', 'Active'), ('SDG_TARGET_10_6', '10.6', 'Ensure enhanced representation and voice for developing countries in decision-making in global international economic and financial institutions in order to deliver more effective, credible, accountable and legitimate institutions', 'Active'), ('SDG_TARGET_10_7', '10.7', 'Facilitate orderly, safe, regular and responsible migration and mobility of people, including through the implementation of planned and well-managed migration policies', 'Active'), ('SDG_TARGET_10_a', '10.a', 'Implement the principle of special and differential treatment for developing countries, in particular least developed countries, in accordance with World Trade Organization agreements', 'Active'), ('SDG_TARGET_10_b', '10.b', 'Encourage official development assistance and financial flows, including foreign direct investment, to States where the need is greatest, in particular least developed countries, African countries, small island developing States and landlocked developing countries, in accordance with their national plans and programmes', 'Active'), ('SDG_TARGET_10_c', '10.c', 'By 2030, reduce to less than 3 per cent the transaction costs of migrant remittances and eliminate remittance corridors with costs higher than 5 per cent', 'Active'), ('SDG_TARGET_11_1', '11.1', 'By 2030, ensure access for all to adequate, safe and affordable housing and basic services and upgrade slums', 'Active'), ('SDG_TARGET_11_2', '11.2', 'By 2030, provide access to safe, affordable, accessible and sustainable transport systems for all, improving road safety, notably by expanding public transport, with special attention to the needs of those in vulnerable situations, women, children, persons with disabilities and older persons', 'Active'), ('SDG_TARGET_11_3', '11.3', 'By 2030, enhance inclusive and sustainable urbanization and capacity for participatory, integrated and sustainable human settlement planning and management in all countries', 'Active'), ('SDG_TARGET_11_4', '11.4', 'Strengthen efforts to protect and safeguard the world’s cultural and natural heritage', 'Active'), ('SDG_TARGET_11_5', '11.5', 'By 2030, significantly reduce the number of deaths and the number of people affected and substantially decrease the direct economic losses relative to global gross domestic product caused by disasters, including water-related disasters, with a focus on protecting the poor and people in vulnerable situations', 'Active'), ('SDG_TARGET_11_6', '11.6', 'By 2030, reduce the adverse per capita environmental impact of cities, including by paying special attention to air quality and municipal and other waste management', 'Active'), ('SDG_TARGET_11_7', '11.7', 'By 2030, provide universal access to safe, inclusive and accessible, green and public spaces, in particular for women and children, older persons and persons with disabilities', 'Active'), ('SDG_TARGET_11_a', '11.a', 'Support positive economic, social and environmental links between urban, peri-urban and rural areas by strengthening national and regional development planning', 'Active'), ('SDG_TARGET_11_b', '11.b', 'By 2020, substantially increase the number of cities and human settlements adopting and implementing integrated policies and plans towards inclusion, resource efficiency, mitigation and adaptation to climate change, resilience to disasters, and develop and implement, in line with the Sendai Framework for Disaster Risk Reduction 2015–2030, holistic disaster risk management at all levels', 'Active'), ('SDG_TARGET_11_c', '11.c', 'Support least developed countries, including through financial and technical assistance, in building sustainable and resilient buildings utilizing local materials', 'Active') ON CONFLICT DO NOTHING;